-- ==============================================================================
-- HOTS TRADING - OFFICIAL AP BOOTS MASTER CATALOG SEED (DATA DARI INPUT & PRICE LIST)
-- Target Database: MariaDB / MySQL (`hotj4796_hotstrading`) & admin.hotstrading.com
-- Generated: October 2026 | Total SKU: 213
-- ==============================================================================

CREATE TABLE IF NOT EXISTS `products` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `product_code` VARCHAR(50) NOT NULL,
  `name` VARCHAR(255) NOT NULL,
  `category` VARCHAR(100) NOT NULL,
  `description` TEXT DEFAULT NULL,
  `base_price` DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  `image_url` VARCHAR(500) DEFAULT NULL,
  `images` TEXT DEFAULT NULL,
  `moq` VARCHAR(50) DEFAULT '12 Pairs',
  `status` ENUM('DRAFT', 'PENDING', 'APPROVED', 'REJECTED') DEFAULT 'APPROVED',
  `is_active` TINYINT(1) DEFAULT 1,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_product_code` (`product_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  `name` = VALUES(`name`),
  `category` = VALUES(`category`),
  `base_price` = VALUES(`base_price`),
  `image_url` = VALUES(`image_url`),
  `moq` = VALUES(`moq`),
  `status` = 'APPROVED',
  `is_active` = 1;
